DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 181", "old_status": "worked_missing_choice", "status": "ready", "question_id": "f1cc1570-c157-509b-a4f9-8d7c9f48f792", "stem": "Point A=(4,7) and points B and C form a triangle. The line through B and C is y=2x+3. Which equation describes the altitude from A to BC?", "choices": [{"key": "A", "text": "y=−2(x−4)+7"}, {"key": "B", "text": "y=−0.5(x−4)+7"}, {"key": "C", "text": "y=2(x−4)+7"}, {"key": "D", "text": "y=0.2(x−4)+7"}], "type": "mcq", "correct": "B", "explanation": "An altitude is perpendicular to BC, so its slope is −1/2. Passing through (4,7), it has equation y−7=−(1/2)(x−4).", "topic": "Coordinate Geometry & Circles", "verification_source": "New exams_251110_.pdf, physical page 460", "note": "Complete original exam page 460 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:HOA 187", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "cd9e9895-ba3e-5565-af3c-cf9ed4088fbb", "stem": "For y=2x−3/(1−x), which statements are true? I. The y-intercept is −5. II. The x-intercept is −3. III. There is no x-intercept. IV. The y-intercept is −3.", "choices": [{"key": "A", "text": "I, II, and III"}, {"key": "B", "text": "I, II, III, and IV"}, {"key": "C", "text": "III and IV"}, {"key": "D", "text": "IV only"}], "type": "mcq", "correct": "C", "explanation": "At x=0, y=−3, so IV is true and I is false. A zero would require 2x(1−x)−3=0, or 2x²−2x+3=0. Its discriminant is 4−24=−20, so there is no real x-intercept: III is true and II false.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 465", "note": "Complete original exam page 465 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:MIX 022", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "129fda0e-2183-56c8-a56e-30877cbf4204", "stem": "Yousef worked 37 hours in week 3. In week 7, he earned $140, which was 10% more than his total earnings in week 3. Approximately how much did he earn per hour in week 3 (nearest tenth of a dollar)?", "choices": [{"key": "A", "text": "$127.27"}, {"key": "B", "text": "$3.4"}, {"key": "C", "text": "$1,400"}, {"key": "D", "text": "$2.8"}], "type": "mcq", "correct": "B", "explanation": "Week-3 earnings were 140/1.10=$127.2727…. Dividing by 37 hours gives $3.4398… per hour, or $3.4 to the nearest tenth.", "topic": "Statistics, Probability & Data Analysis", "verification_source": "New exams_251110_.pdf, physical page 411", "note": "Complete original exam page 411 visually checked; answer independently solved and all choices checked. The original chart confirms 37 hours in week 3; the complete pay comparison and all choices are restored.", "assets": {}}, {"id": "clean:PAM 004", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "6e358bf7-67f0-564a-b30d-dd74c27e9700", "stem": "For x≠3, y=(x³−3x²+2x−1)/(x−3). Which expression is equivalent to y?", "choices": [{"key": "A", "text": "x²+2+5/(x−3)"}, {"key": "B", "text": "x²−2x+2+3/(x−3)"}, {"key": "C", "text": "x²−3−8/(x−3)"}, {"key": "D", "text": "x²+2"}], "type": "mcq", "correct": "A", "explanation": "Polynomial division gives x³−3x²+2x−1=(x−3)(x²+2)+5. Therefore y=x²+2+5/(x−3).", "topic": "Algebra Foundations, Equations & Inequalities", "verification_source": "New exams_251110_.pdf, physical page 8", "note": "Complete original exam page 8 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:PAM 009", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "030111d7-2349-5dab-8638-e5dcf9a55a06", "stem": "The graph depicts y=f(x). How many real solutions does f(x)=0.5 have?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}], "type": "mcq", "correct": "D", "explanation": "Draw the horizontal line y=0.5. It crosses each outer branch once and crosses the two branches on either side of the local maximum once each, giving four intersections.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 13", "note": "Complete original exam page 13 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PAM 036", "old_status": "needs_source_reconstruction", "status": "duplicate", "note": "Complete original exam page 101 visually checked; answer independently solved and all choices checked.  Worked solution: The vertex is (1,0), and the symmetry axis is x=1. The graph passes through (0,−1), giving y=−(x−1)²=−x²+2x−1. Thus I and III are true.", "correct": "D", "question_id": "b515a6ed-1c6f-5848-b2b4-12c02a5d4524", "duplicate_of": "topic:AAF 048"}, {"id": "clean:PAM 037", "old_status": "needs_source_reconstruction", "status": "duplicate", "note": "Complete original exam page 101 visually checked; answer independently solved and all choices checked.  Worked solution: The vertex is (1,0). At the vertex of this vertical parabola the tangent is horizontal, so its equation is y=0.", "correct": "B", "question_id": "0f808148-2950-5c6c-b3de-637ce88d6c56", "duplicate_of": "topic:AAF 050"}, {"id": "clean:PSD 005", "old_status": "worked_missing_choice", "status": "ready", "question_id": "92d0faed-498b-590a-acac-84e4bdb2c5d8", "stem": "If 1/(x−y)=3/(5y), with both sides defined, what is x/y?", "choices": [{"key": "A", "text": "3/8"}, {"key": "B", "text": "8/3"}, {"key": "C", "text": "8/15"}, {"key": "D", "text": "15/8"}], "type": "mcq", "correct": "B", "explanation": "Cross-multiply: 5y=3(x−y), so 8y=3x. Since y≠0, x/y=8/3.", "topic": "Algebra Foundations, Equations & Inequalities", "verification_source": "New exams_251110_.pdf, physical page 8", "note": "Complete original exam page 8 visually checked; answer independently solved and all choices checked. ", "assets": {}}, {"id": "clean:PSD 007", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "5851be5d-d48c-56ec-80aa-d6f8d05f466b", "stem": "Which equation is represented by the graph?", "choices": [{"key": "A", "text": "y=−(2/5)x−3"}, {"key": "B", "text": "y=(2/5)x+3"}, {"key": "C", "text": "y=−(2/5)x+3"}, {"key": "D", "text": "y=−(5/2)x+3"}], "type": "mcq", "correct": "C", "explanation": "The line crosses the y-axis at 3. Moving 5 units right reduces y by 2, so its slope is −2/5. Hence y=−(2/5)x+3.", "topic": "Functions, Transformations & Graphs", "verification_source": "New exams_251110_.pdf, physical page 10", "note": "Complete original exam page 10 visually checked; answer independently solved and all choices checked. ", "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "clean:PSD 012", "old_status": "worked_missing_choice", "status": "ready", "question_id": "d974a625-b685-569f-95e5-dec8ec148a20", "stem": "A craftsman buys a 10-kg jars and b 25-kg jars of paint. The jars cost $45 and $120 each, respectively. The load must not exceed 250 kg, and he must spend at least $900 to receive a discount. Which system describes these constraints (a,b are nonnegative integers)?", "choices": [{"key": "A", "text": "10a+25b≥250 and 45a+120b≤900"}, {"key": "B", "text": "10a+25b≤250 and 45a+120b≤900"}, {"key": "C", "text": "10a+25b≥250 and 45a+120b≥900"}, {"key": "D", "text": "10a+25b≤250 and 45a+120b≥900"}], "type": "mcq", "correct": "D", "explanation": "The total mass is 10a+25b kg and must not exceed 250. The total cost is 45a+120b dollars and must be at least 900. Thus 10a+25b≤250 and 45a+120b≥900.", "topic": "Algebra Foundations, Equations & Inequalities", "verification_source": "New exams_251110_.pdf, physical page 12", "note": "Complete original exam page 12 visually checked; answer independently solved and all choices checked. ", "assets": {}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260929') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260929','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260929'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF q.id IS NOT NULL AND NOT (v ? 'before') THEN RAISE EXCEPTION 'Unexpected existing target %',qid; END IF;
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',coalesce(v->>'verification_source',s.source_document||' page '||s.source_page));
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260929','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260929','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-29-independent-solution-and-source-check','answer_review','2026-09-29-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-29. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260929';
